package com.agencytrip.agencytripapi.infrastructure.adapter.out.persistence;
import com.agencytrip.agencytripapi.domain.model.*; import com.agencytrip.agencytripapi.domain.port.out.TravelRepositoryPort; import com.agencytrip.agencytripapi.infrastructure.adapter.out.persistence.entity.*; import java.util.*; import java.util.function.*; import org.springframework.stereotype.Component;
@Component
public class JpaTravelRepositoryAdapter implements TravelRepositoryPort {
 private final UserJpaRepository users; private final RoleJpaRepository roles; private final DestinationJpaRepository destinations; private final HotelJpaRepository hotels; private final TransportJpaRepository transports; private final PackageJpaRepository packages; private final ReservationJpaRepository reservations; private final PaymentJpaRepository payments;
 public JpaTravelRepositoryAdapter(UserJpaRepository a,RoleJpaRepository b,DestinationJpaRepository c,HotelJpaRepository d,TransportJpaRepository e,PackageJpaRepository f,ReservationJpaRepository g,PaymentJpaRepository h){users=a;roles=b;destinations=c;hotels=d;transports=e;packages=f;reservations=g;payments=h;}
 public Optional<User> findUserByEmail(String v){return users.findByCorreo(v).map(this::user);} public Optional<User> findUserById(int v){return users.findById(v).map(this::user);} public boolean emailExists(String e,Integer x){return x==null?users.existsByCorreo(e):users.existsByCorreoAndIdUsuarioNot(e,x);} public List<User> findActiveUsers(){return users.findByEstadoTrue().stream().map(this::user).toList();} public User saveUser(User v){return user(users.save(userEntity(v)));} public Optional<Role> findRole(int v){return roles.findById(v).map(this::role);} public List<Role> findRoles(){return roles.findAll().stream().map(this::role).toList();}
 public List<Destination> findActiveDestinations(){return destinations.findByEstadoTrue().stream().map(this::destination).toList();} public Optional<Destination> findDestination(int v){return destinations.findById(v).map(this::destination);} public Destination saveDestination(Destination v){return destination(destinations.save(destinationEntity(v)));}
 public List<Hotel> findActiveHotels(){return hotels.findByEstadoTrue().stream().map(this::hotel).toList();} public Optional<Hotel> findHotel(int v){return hotels.findById(v).map(this::hotel);} public Hotel saveHotel(Hotel v){return hotel(hotels.save(hotelEntity(v)));}
 public List<Transport> findActiveTransports(){return transports.findByEstadoTrue().stream().map(this::transport).toList();} public Optional<Transport> findTransport(int v){return transports.findById(v).map(this::transport);} public Transport saveTransport(Transport v){return transport(transports.save(transportEntity(v)));}
 public List<PackageTrip> findActivePackages(){return packages.findByEstadoTrue().stream().map(this::trip).toList();} public Optional<PackageTrip> findPackage(int v){return packages.findById(v).map(this::trip);} public PackageTrip savePackage(PackageTrip v){return trip(packages.save(packageEntity(v)));}
 public List<Reservation> findReservations(){return reservations.findAll().stream().map(this::reservation).toList();} public List<Reservation> findReservationsByUser(int v){return reservations.findByIdUsuario(v).stream().map(this::reservation).toList();} public Optional<Reservation> findReservation(int v){return reservations.findById(v).map(this::reservation);} public Reservation saveReservation(Reservation v){return reservation(reservations.save(reservationEntity(v)));}
 public List<Payment> findPayments(){return payments.findAll().stream().map(this::payment).toList();} public List<Payment> findPaymentsByUser(int v){return payments.findByReservaIdUsuario(v).stream().map(this::payment).toList();} public Optional<Payment> findPayment(int v){return payments.findById(v).map(this::payment);} public boolean hasApprovedPayment(int v){return payments.existsByIdReservaAndEstado(v,"APROBADO");} public Payment savePayment(Payment v){return payment(payments.save(paymentEntity(v)));}
 private Role role(RoleEntity e){Role v=new Role();v.setIdRol(e.getIdRol());v.setNombre(e.getNombre());return v;} private User user(UserEntity e){User v=new User();v.setIdUsuario(e.getIdUsuario());v.setNombre(e.getNombre());v.setApellido(e.getApellido());v.setCorreo(e.getCorreo());v.setPassword(e.getPassword());v.setIdRol(e.getIdRol());v.setFechaRegistro(e.getFechaRegistro());v.setEstado(e.isEstado());if(e.getRol()!=null)v.setRol(role(e.getRol()));return v;} private UserEntity userEntity(User v){UserEntity e=new UserEntity();e.setIdUsuario(v.getIdUsuario());e.setNombre(v.getNombre());e.setApellido(v.getApellido());e.setCorreo(v.getCorreo());e.setPassword(v.getPassword());e.setIdRol(v.getIdRol());e.setFechaRegistro(v.getFechaRegistro());e.setEstado(v.isEstado());return e;}
 private Destination destination(DestinationEntity e){Destination v=new Destination();v.setIdDestino(e.getIdDestino());v.setNombre(e.getNombre());v.setPais(e.getPais());v.setDescripcion(e.getDescripcion());v.setImagen(e.getImagen());v.setEstado(e.isEstado());return v;} private DestinationEntity destinationEntity(Destination v){DestinationEntity e=new DestinationEntity();e.setIdDestino(v.getIdDestino());e.setNombre(v.getNombre());e.setPais(v.getPais());e.setDescripcion(v.getDescripcion());e.setImagen(v.getImagen());e.setEstado(v.isEstado());return e;}
 private Hotel hotel(HotelEntity e){Hotel v=new Hotel();v.setIdHotel(e.getIdHotel());v.setNombre(e.getNombre());v.setDireccion(e.getDireccion());v.setCiudad(e.getCiudad());v.setCategoria(e.getCategoria());v.setDescripcion(e.getDescripcion());v.setEstado(e.isEstado());return v;} private HotelEntity hotelEntity(Hotel v){HotelEntity e=new HotelEntity();e.setIdHotel(v.getIdHotel());e.setNombre(v.getNombre());e.setDireccion(v.getDireccion());e.setCiudad(v.getCiudad());e.setCategoria(v.getCategoria());e.setDescripcion(v.getDescripcion());e.setEstado(v.isEstado());return e;}
 private Transport transport(TransportEntity e){Transport v=new Transport();v.setIdTransporte(e.getIdTransporte());v.setTipo(e.getTipo());v.setEmpresa(e.getEmpresa());v.setDescripcion(e.getDescripcion());v.setEstado(e.isEstado());return v;} private TransportEntity transportEntity(Transport v){TransportEntity e=new TransportEntity();e.setIdTransporte(v.getIdTransporte());e.setTipo(v.getTipo());e.setEmpresa(v.getEmpresa());e.setDescripcion(v.getDescripcion());e.setEstado(v.isEstado());return e;}
 private PackageTrip trip(PackageEntity e){PackageTrip v=new PackageTrip();v.setIdPaquete(e.getIdPaquete());v.setNombre(e.getNombre());v.setDescripcion(e.getDescripcion());v.setPrecio(e.getPrecio());v.setFechaSalida(e.getFechaSalida());v.setFechaRegreso(e.getFechaRegreso());v.setCupos(e.getCupos());v.setIdDestino(e.getIdDestino());v.setIdTransporte(e.getIdTransporte());v.setIdHotel(e.getIdHotel());v.setEstado(e.isEstado());if(e.getDestino()!=null)v.setDestino(destination(e.getDestino()));if(e.getTransporte()!=null)v.setTransporte(transport(e.getTransporte()));if(e.getHotel()!=null)v.setHotel(hotel(e.getHotel()));return v;} private PackageEntity packageEntity(PackageTrip v){PackageEntity e=new PackageEntity();e.setIdPaquete(v.getIdPaquete());e.setNombre(v.getNombre());e.setDescripcion(v.getDescripcion());e.setPrecio(v.getPrecio());e.setFechaSalida(v.getFechaSalida());e.setFechaRegreso(v.getFechaRegreso());e.setCupos(v.getCupos());e.setIdDestino(v.getIdDestino());e.setIdTransporte(v.getIdTransporte());e.setIdHotel(v.getIdHotel());e.setEstado(v.isEstado());return e;}
 private Reservation reservation(ReservationEntity e){Reservation v=new Reservation();v.setIdReserva(e.getIdReserva());v.setIdUsuario(e.getIdUsuario());v.setIdPaquete(e.getIdPaquete());v.setFechaReserva(e.getFechaReserva());v.setCantidadPersonas(e.getCantidadPersonas());v.setPrecioTotal(e.getPrecioTotal());v.setEstado(e.getEstado());if(e.getUsuario()!=null)v.setUsuario(user(e.getUsuario()));if(e.getPaquete()!=null)v.setPaquete(trip(e.getPaquete()));return v;} private ReservationEntity reservationEntity(Reservation v){ReservationEntity e=new ReservationEntity();e.setIdReserva(v.getIdReserva());e.setIdUsuario(v.getIdUsuario());e.setIdPaquete(v.getIdPaquete());e.setFechaReserva(v.getFechaReserva());e.setCantidadPersonas(v.getCantidadPersonas());e.setPrecioTotal(v.getPrecioTotal());e.setEstado(v.getEstado());return e;}
 private Payment payment(PaymentEntity e){Payment v=new Payment();v.setIdPago(e.getIdPago());v.setIdReserva(e.getIdReserva());v.setFechaPago(e.getFechaPago());v.setMonto(e.getMonto());v.setMetodoPago(e.getMetodoPago());v.setEstado(e.getEstado());if(e.getReserva()!=null)v.setReserva(reservation(e.getReserva()));return v;} private PaymentEntity paymentEntity(Payment v){PaymentEntity e=new PaymentEntity();e.setIdPago(v.getIdPago());e.setIdReserva(v.getIdReserva());e.setFechaPago(v.getFechaPago());e.setMonto(v.getMonto());e.setMetodoPago(v.getMetodoPago());e.setEstado(v.getEstado());return e;}
}
